DROP TABLE IF EXISTS `fin_changed_deleted_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `fin_changed_deleted_transactions` (
  `AuditID` bigint(20) NOT NULL AUTO_INCREMENT,
  `action_type` enum('EDIT','DELETE') NOT NULL COMMENT 'What happened: EDIT or DELETE',
  `original_tid` int(11) NOT NULL COMMENT 'TID from fin_studentfeestracking',
  `orig_regno` varchar(50) NOT NULL,
  `orig_trans_type` varchar(20) NOT NULL,
  `orig_item_code` int(11) NOT NULL,
  `orig_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `orig_detail` varchar(255) DEFAULT NULL,
  `orig_trans_date` date DEFAULT NULL,
  `orig_acadyear` varchar(30) DEFAULT NULL,
  `orig_semester` tinyint(4) DEFAULT NULL,
  `orig_post_status` varchar(20) DEFAULT NULL,
  `new_trans_type` varchar(20) DEFAULT NULL,
  `new_item_code` int(11) DEFAULT NULL,
  `new_amount` decimal(15,2) DEFAULT NULL,
  `new_detail` varchar(255) DEFAULT NULL,
  `new_trans_date` date DEFAULT NULL,
  `new_acadyear` varchar(30) DEFAULT NULL,
  `new_semester` tinyint(4) DEFAULT NULL,
  `new_post_status` varchar(20) DEFAULT NULL,
  `changed_by` varchar(100) NOT NULL COMMENT 'Username of the person who made this change',
  `changed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Timestamp of the action',
  `ip_address` varchar(50) DEFAULT NULL COMMENT 'IP address of the user',
  `reason` varchar(500) DEFAULT NULL COMMENT 'Optional reason for the change',
  PRIMARY KEY (`AuditID`),
  KEY `idx_original_tid` (`original_tid`),
  KEY `idx_regno` (`orig_regno`),
  KEY `idx_action` (`action_type`),
  KEY `idx_changed_at` (`changed_at`),
  KEY `idx_changed_by` (`changed_by`)
) ENGINE=InnoDB AUTO_INCREMENT=250 DEFAULT CHARSET=utf8mb4 COMMENT='Immutable audit trail of all edited and deleted fee transactions';
